  background:var(--bg-content);
  color:var(--base);
  font-family:var(--font-body);
  font-size:var(--fs-base);
  line-height:var(--lh-base);
  -webkit-font-smoothing:antialiased;
}
[hidden]{display:none!important}
/* utils.less:142 — a GLOBAL rule, and the design QA found it by measuring the
   product's Clear filters button at opacity 0.54 while ours sat at 1. Anything
   disabled anywhere in Profolio is dimmed and inert. */
[disabled]{opacity:var(--disabled-opacity);pointer-events:none}
a{text-decoration:none;color:inherit}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
