/* A page state stacks its children the way the content area does, so that the
   pager can sit at the END of the row the way the product's does. As a plain
   block the pager's `margin-inline-start:auto` never took, and it measured at
   x=84 against the product's 1108 — the right size in the wrong place. */
[data-state-panel]{display:grid;gap:var(--sp-8);align-content:start}
[data-state-panel][hidden]{display:none}

/* the component */
/* ═══════════════════════════════════════════════════════════════════════
   COMPONENT · icon-rail-item
   src/layout/style.js .ant-layout-sider .ant-menu-item
   ═══════════════════════════════════════════════════════════════════════ */
.pf-rail{
  width:var(--rail-w);
  background:var(--sider-bg);
  box-shadow:var(--shadow-sider);
  border-inline-end:var(--border-w) solid var(--gray-400);
  padding-block:var(--rail-pad-block) var(--one-10);
  display:flex;
  flex-direction:column;
  align-items:center;
}
.pf-rail-brand{
  height:var(--header-h);
  display:grid;
  align-content:center;
  justify-content:start;
  width:100%;
  /* the wordmark is 205px wide and the rail is 60px: on the live screen you
     see its leading mark and nothing else, because the rail clips it */
  overflow:hidden;
  padding-inline-start:var(--rail-brand-inset);
}
.pf-rail-logo{
  display:grid;
  place-content:center;
  /* ProfolioLogo carries its own #28B16D mark and #222 wordmark, so nothing
     here needs to set a colour. */
}
.pf-rail-list{
  flex:1;
  width:100%;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:var(--sp-0);
  min-height:var(--sp-0);
}
.pf-rail-item{
  width:var(--rail-item-w);
  height:var(--rail-item-h);
  margin-block:var(--rail-item-margin);
  display:flex;
  align-items:center;
  justify-content:center;
  padding-inline:var(--rail-item-pad-inline);
  margin-inline:auto;
  border-radius:var(--radius-control);
  color:var(--gray-700);
  font-weight:var(--fw-500);
  text-align:center;
}
.pf-rail-item svg{width:var(--rail-icon);height:var(--rail-icon)}
.pf-rail-item:hover,
.pf-rail-item[data-state="hover"]{color:var(--primary)}
.pf-rail-item[aria-current="page"],
.pf-rail-item[data-state="active"]{
  background:var(--primary-light-4);
  color:var(--primary);
  font-weight:var(--fw-600);
}
.pf-rail-bottom{
  display:flex;
  flex-direction:column;
  gap:var(--rail-bottom-gap);
  width:100%;
  padding-inline:var(--sp-8);
}
