.pf-credit-actions > .pf-btn{width:100%}
/* inline-block, not block: these sit beside text as often as they sit in a
   flex row, and `display:block` pushes them onto a line of their own */
.i{display:inline-block;vertical-align:middle;width:1.2em;height:1.2em;flex:none}
