   (filters.js passes style={{border:0, margin:2}}), icon after the label. */
.pf-filter-actions .pf-btn[data-variant="tint"]{
  font-size:var(--fs-showmore);font-weight:var(--fw-700);
  color:var(--showmore-fg);
  border:0;
  margin:var(--sp-2);
  gap:var(--sp-8);
}
.pf-filter-actions .pf-btn[data-variant="primary"]{font-size:var(--fs-search);font-weight:var(--fw-700)}
.pf-filter-actions .pf-btn[data-variant="primary"]{height:var(--filter-search-h);padding-inline:var(--filter-search-pad)}
/* two more button variants the filter bar introduces — button/styled.js */
.pf-btn[data-variant="tint"]{--btn-bg:var(--primary-light-4);--btn-fg:var(--gray-color);--btn-bd:transparent}
/* Show More: type default on the primary tint */
.pf-btn[data-variant="link-danger"]{--btn-bg:transparent;--btn-fg:var(--danger);--btn-bd:transparent;padding-inline:var(--sp-0)}
/* Clear filters: type="link" danger */
.pf-btn span + svg{margin-inline-start:var(--btn-icon-gap)}
/* the page's own loading state dims the Search button, as antd does while a
   query is open — measured at 0.65 on .ant-btn-loading */
body[data-page-state="loading"] .pf-filter-actions .pf-btn[data-variant="primary"]{
  opacity:var(--loading-opacity);pointer-events:none;
}
.pf-health-item .pf-btn{flex:none}
.pf-detail-gallery .pf-btn{position:absolute;inset-block-end:var(--sp-12);inset-inline-start:var(--sp-12)}
.pf-field[data-spaced="true"] .pf-btn{block-size:var(--service-control-h)}
.pf-completion-head .pf-btn{padding:var(--sp-0);border:0;background:none;white-space:nowrap}
.pf-btn[data-variant="round"]{
  inline-size:var(--round-w);block-size:var(--sfield-round-h);
  display:inline-flex;align-items:center;justify-content:center;gap:var(--sp-8);
  border:0;border-radius:32px;
  background:var(--primary-light-4);color:var(--primary);
  font-size:var(--fs-13);font-weight:var(--fw-600);
}
.pf-form-actions .pf-btn{inline-size:var(--save-w);block-size:40px;border-radius:var(--save-r, var(--radius-control))}

